class Solution {
    public int medianII(int[] nums) {
        if(nums.length == 0){
            return 0;
        }
        int left = 0;
        int right = nums.length - 1;
        int mid = (left + right) / 2;
        int[] temp = new int[nums.length];
        for(int i = 0; i < nums.length; i++){
            temp[i] = nums[i];
        }
        Arrays.sort(temp);
        while(left <= right){
            int mid = (left + right) / 2;
            if(mid == 0){
                return temp[mid];
            }else if(mid == temp.length - 1){
                return temp[mid];
            }else{
                if(temp[mid - 1] < temp[mid] && temp[mid] < temp[mid + 1]){
                    return temp[mid];
                }else if(temp[mid - 1] > temp[mid]){
                    right = mid - 1;
                }else{
                    left = mid + 1;
                }
            }
        }
        return 0;
    }
}
